//! JIS X 0208's ideograph repertoire (ADR 0039): the fixed,
//! dictionary-free set that separates an ideograph Japanese text uses
//! from one only another language's orthography uses. A bitset over
//! the CJK Unified Ideographs block (U+4E00–U+9FFF); every ideograph
//! outside that block — the extension blocks, the compatibility
//! ideographs — is outside the repertoire by definition.
//!
//! Generated by `scripts/gen_jis_x0208.py` from Python's `shift_jis`
//! codec (JIS X 0208:1997); regenerate rather than edit. The rule that
//! reads it is `mechanical::foreign_ideographs`.

/// Whether `c` is a CJK ideograph at all — the Unified Ideographs
/// block, its extension blocks, or the compatibility ideographs.
/// Kana, punctuation, and every non-ideograph are not judged.
pub(super) fn is_ideograph(c: char) -> bool {
    matches!(
        c as u32,
        0x3400..=0x4DBF | 0x4E00..=0x9FFF | 0xF900..=0xFAFF | 0x20000..=0x3134F
    )
}

/// Whether `c` is an ideograph in JIS X 0208's repertoire.
pub(super) fn in_jis_x0208(c: char) -> bool {
    let n = c as u32;
    if !(0x4E00..=0x9FFF).contains(&n) {
        return false;
    }
    let bit = n - 0x4E00;
    JIS_X0208_IDEOGRAPHS[(bit / 64) as usize] & (1u64 << (bit % 64)) != 0
}

